rows=[
dict(title='Boonta Eve Podrace',type='Epic Event',original_set='Tatooine',set_icon='Tatooine',destiny='0',uniqueness='Non-unique',icons=['Epic Event','Episode I'],lore=None,game_text='Deploy on Podrace Arena. Once per game, either player may initiate a Podrace: During opponent’s control phase, each player may draw one race destiny. Each player may place any drawn race destiny on their Podracer (or on Podrace Arena if they have none) or in their Used Pile. During any move phase, winner is any player with a race total &gt; 24 and greater than opponent’s highest race total. Winner retrieves 6 Force and loser loses 6 Force. Place all race destiny cards in owner’s Used Piles and all Podracers are lost.'),
dict(title='Brisky Morning Munchen',type='Effect',original_set='Tatooine',set_icon='Tatooine',destiny='3',icons=['Effect','Episode I'],lore='“Den boom! Getten berry scared, and grabben dat Jedi, and pow! Mesa here. Huh! Mesa getten berry, berry scared. Mmm.”',game_text='Deploy on table. Once per game, may deploy Jar Jar from Reserve Deck; reshuffle. If you just lost Jar Jar from a site, may place him here. At any time, may use 3 Force to take Jar Jar from here into hand.'),
dict(title='Chewbacca, Protector',type='Character',subtype='Rebel',original_set='Reflections II: Expanding the Galaxy',set_icon='Reflections II',destiny='1',power='6',ability='2',armor='4',deploy='5',forfeit='6',icons=['Rebel','Pilot','Warrior'],lore='Chewie honored his life debt to Han by protecting Leia. Posed as the mercenary Snoova while on Coruscant. Smuggler. Wookiee.',game_text='Deploys −3 to same site as Leia. Adds 2 to power of anything he pilots (3 if Falcon). Once per turn, may target opponent’s character at same site who has power &lt; 4 and cancel target’s game text for remainder of turn.'),
dict(title='Echo Base Garrison',type='Effect',original_set='Third Anthology',set_icon='Premium',destiny='4',icons=['Effect'],lore='“All troop carriers will assemble at the north entrance. The heavy transport ships will leave as soon as they’re loaded.”',game_text='Deploy on table. Rogue T-47s are immune to attrition &lt; 4 (or &lt; 6 if matching pilot aboard). Once during each of your turns, may take one maintenance droid, Bacta Tank, Lone Rogue, [[File:Icon-set-Hoth.png|20px|link=Hoth]] Luke, [[File:Icon-set-Special-Edition.png|20px|link=Special Edition]] Wedge, Zev, or Hobbie into hand from Reserve Deck; reshuffle.'),
dict(title='End Of A Reign',type='Interrupt',subtype='Used or Lost Interrupt',original_set='Tatooine',set_icon='Tatooine',destiny='4',icons=['Interrupt'],lore='The turning of Vader and the loss of Palpatine was the beginning of a new era for the entire galaxy.',game_text='USED: Cancel Overseeing It Personally. OR Use 4 Force to cancel Vader’s game text for remainder of turn.<br />LOST: If Emperor just lost from table, draw destiny. Opponent must lose Force equal to the destiny draw.'),
dict(title='Gimme A Lift!',type='Interrupt',subtype='Used Interrupt',original_set='Theed Palace',set_icon='Theed Palace',destiny='5',icons=['Interrupt','Episode I'],lore='Jar Jar Binks’s courage on the battlefield put quite a thorn in the Trade Federation’s side. Many believed it wasn’t actually courage.',game_text='Relocate Jar Jar to a battle just initiated at an adjacent site. OR Increase Jar Jar’s landspeed by 1 for remainder of turn. OR If Jar Jar on Brisky Morning Munchen, take him into hand.'),
dict(title='I Did It!',type='Epic Event',original_set='Tatooine',set_icon='Tatooine',destiny='0',icons=['Epic Event','Episode I'],lore=None,game_text='Deploy on table if you’ve won a Podrace. Once per game, may place Boonta Eve Podrace out of play to retrieve 4 Force. If you occupy a battleground site and a battleground system, once during each of your control phases may take the bottom card of your Lost Pile and place it on top of your Force Pile. At the end of opponent’s turn opponent must lose 2 Force or place their Force Pile onto their Used Pile.'),
dict(title='Lando With Vibro-Ax',type='Character',subtype='Alien',original_set="Jabba's Palace Sealed Deck",set_icon='Premium',destiny='1',power='4',ability='3',printed_label='Force-Attuned',deploy='4',forfeit='6',icons=['Alien','Pilot','Warrior','Permanent weapon'],lore='Gambler. Spy in Jabba’s Court. Has walked the palace’s passageways and overheard many details of Jabba’s operations on Tatooine.',game_text='Deploys −2 on Tatooine. When at a Tatooine site, adds one battle destiny. Permanent weapon is vibro-ax (may target character for free; both players draw destiny; target excluded from battle if your destiny +4 &gt; target’s power + opponent’s destiny).'),
dict(title="Obi-Wan's Journal",type='Device',original_set='Reflections II: Expanding the Galaxy',set_icon='Reflections II',destiny='2',icons=['Device'],lore='Written by Obi-Wan Kenobi. Used by Luke to construct his lightsaber. Contained instructions on building required tools as well. Keyed to self-destruct if not opened by Luke.',game_text='Deploy on Luke or Obi-Wan. Your characters present armed with a unique (•) lightsaber Weapon card are immune to Disarmed, once per battle may cancel a weapon destiny just drawn, and that lightsaber’s Force drain modifiers may not be canceled. Lost if stolen.'),
dict(title='Outrider',type='Starship',subtype='Starfighter',model='Modified Light Freighter',original_set='Reflections II: Expanding the Galaxy',set_icon='Reflections II',destiny='2',power='3',maneuver='4',hyperspeed='5',deploy='2',forfeit='5',icons=['Starship','Scomp link','Nav computer','Independent'],lore='Highly modified Corellian Engineering Corporation YT-2400. KonGar KGDefender military grade ion engines. Griffyn/Y2TG hyperdrive. Never boarded by Imperial customs.',game_text='May add 2 pilots and 1 passenger. Utinni Effects which retrieve Force are immune to Alter, but are placed out of play when completed. While Dash or Leebo piloting, immune to attrition &lt; 4.')]
